pub fn dispatch_set_identity(
    repo: &mut impl crate::kernel::Repository<CollectionIdentity>,
    id: &str,
    args: SetIdentityArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<CollectionIdentity> {
    args.identity_field.check_invariants()?;
    if let Some(v) = &args.identity_source {
        v.check_invariants()?;
    }
    if let Some(v) = &args.identity_prefix {
        v.check_invariants()?;
    }
    if let Some(v) = &args.identity_extra_json {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, COLLECTION_IDENTITY_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "SetIdentity",
        "ConsoleSettings::CollectionIdentity",
        "CollectionIdentity",
        "agg.value",
        &with_references,
        &[],
        None,
        |record| {
            record.identity_field = Some(args.identity_field.clone());
            record.identity_strategy = Some(args.identity_strategy.clone());
            record.identity_source = args.identity_source.clone();
            record.identity_prefix = args.identity_prefix.clone();
            record.identity_extra_json = args.identity_extra_json.clone();
            Ok(())
        },
        &[],
        &collectionidentity_invariants(),
        &["CollectionIdentified"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

